export function Logo({
  tone = "light",
  className,
}: {
  tone?: "light" | "dark";
  className?: string;
}) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", className)}>
      <Glyph className="size-8 shrink-0" />
      <span
        className={cn(
          "text-[19px] font-semibold tracking-[-0.035em]",
          tone === "dark" ? "text-white" : "text-ink",
        )}
      >
        nookat
      </span>
    </span>
  );
}

