const isExternal = (href: string) => /^https?:/.test(href);

export function externalProps(href: string) {
  return isExternal(href)
    ? { target: "_blank", rel: "noreferrer noopener" }
    : {};
}

const buttonBase =
  "group inline-flex select-none items-center justify-center gap-2 rounded-[10px] font-medium tracking-[-0.01em] transition-[background-color,border-color,color,transform] duration-200 active:translate-y-px";

export function PrimaryButton({
  href,
  children,
  className,
  tone = "ink",
  trailing = "arrow",
}: {
  href: string;
  children: ReactNode;
  className?: string;
  tone?: "ink" | "blue";
  trailing?: "arrow" | "external" | "none";
}) {
  return (
    <a
      href={href}
      {...externalProps(href)}
      className={cn(
        buttonBase,
        "h-12 pl-5 pr-2 text-[15px]",
        tone === "ink"
          ? "bg-ink text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.12)] hover:bg-ink-2"
          : "bg-blue-strong text-white hover:bg-blue-strong-hover",
        trailing === "none" && "pr-5",
        className,
      )}
    >
      {children}
      {trailing !== "none" && (
        <span
          className={cn(
            "grid size-8 place-items-center rounded-[7px] transition-transform duration-200",
            tone === "ink" ? "bg-blue text-white" : "bg-white/15 text-white",
            trailing === "arrow"
              ? "group-hover:translate-x-0.5"
              : "group-hover:-translate-y-0.5 group-hover:translate-x-0.5",
          )}
        >
          {trailing === "arrow" ? (
            <ArrowRight className="size-4" strokeWidth={2.2} />
          ) : (
            <ArrowUpRight className="size-4" strokeWidth={2.2} />
          )}
        </span>
      )}
    </a>
  );
}

export function SecondaryButton({
  href,
  children,
  className,
}: {
  href: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <a
      href={href}
      {...externalProps(href)}
      className={cn(
        buttonBase,
        "h-12 border border-line-2 px-5 text-[15px] text-ink hover:border-ink/40 hover:bg-paper-2",
        className,
      )}
    >
      {children}
    </a>
  );
}

export function TextLink({
  href,
  children,
  className,
}: {
  href: string;
  children: ReactNode;
  className?: string;
}) {
  const external = isExternal(href);
  const Icon = external ? ArrowUpRight : ArrowRight;
  return (
    <a
      href={href}
      {...externalProps(href)}
      className={cn(
        "group inline-flex items-center gap-1.5 font-medium underline decoration-current/25 underline-offset-[5px] transition-colors hover:decoration-current",
        className,
      )}
    >
      {children}
      <Icon
        className={cn(
          "size-3.5 transition-transform",
          external
            ? "group-hover:-translate-y-0.5 group-hover:translate-x-0.5"
            : "group-hover:translate-x-0.5",
        )}
        strokeWidth={2}
      />
    </a>
  );
}

/** Section heading: a display title with an optional lede beside it. No eyebrow. */
export function SectionHead({
  id,
  title,
  lede,
  tone = "light",
  className,
}: {
  id?: string;
  title: ReactNode;
  lede?: ReactNode;
  tone?: "light" | "dark";
  className?: string;
}) {
  const dark = tone === "dark";
  return (
    <div
      className={cn(
        "mb-10 grid gap-5 md:mb-14 md:grid-cols-12 md:items-end md:gap-8",
        className,
      )}
    >
      <h2
        id={id}
        className={cn(
          "display text-[clamp(2.1rem,4.6vw,3.5rem)] md:col-span-7",
          dark ? "text-on-navy" : "text-ink",
        )}
      >
        {title}
      </h2>
      {lede && (
        <p
          className={cn(
            "max-w-[34rem] text-[16px] leading-[1.6] md:col-span-5 md:justify-self-end",
            dark ? "text-on-navy-muted" : "text-muted",
          )}
        >
          {lede}
        </p>
      )}
    </div>
  );
}
